sp_widget.client_script:
api.controller = function($scope) {

    var c = this;

    $scope.monthNames = [
        "January",
        "February",
        "March",
        "April",
        "May",
        "June",
        "July",
        "August",
        "September",
        "October",
        "November",
        "December"
    ];

    var today = new Date();

    $scope.currentMonth = today.getMonth();
    $scope.currentYear = today.getFullYear();

    $scope.days = [];
    $scope.blanks = [];


    function buildCalendar() {

        $scope.days = [];
        $scope.blanks = [];

        var firstDay =
            new Date(
                $scope.currentYear,
                $scope.currentMonth,
                1
            ).getDay();

        var totalDays =
            new Date(
                $scope.currentYear,
                $scope.currentMonth + 1,
                0
            ).getDate();


        for (var i = 0; i < firstDay; i++) {
            $scope.blanks.push(i);
        }


        for (var day = 1; day <= totalDays; day++) {

            var dayObj = {
                date: day,
                leaves: []
            };

            var currentDate =
                new Date(
                    $scope.currentYear,
                    $scope.currentMonth,
                    day
                );

            angular.forEach(
                c.data.approvedLeaves,
                function(leave) {

                    if (!leave.startDate ||
                        !leave.endDate)
                        return;

                    var startParts =
                        leave.startDate.split("-");

                    var endParts =
                        leave.endDate.split("-");

                    var startDate =
                        new Date(
                            parseInt(startParts[0], 10),
                            parseInt(startParts[1], 10) - 1,
                            parseInt(startParts[2], 10)
                        );

                    var endDate =
                        new Date(
                            parseInt(endParts[0], 10),
                            parseInt(endParts[1], 10) - 1,
                            parseInt(endParts[2], 10)
                        );

                    if (currentDate >= startDate &&
                        currentDate <= endDate) {

                        dayObj.leaves.push({
                            employee: leave.employee,
                            leaveType: leave.leaveType,
                            number: leave.number
                        });
                    }
                }
            );

            $scope.days.push(dayObj);
        }
    }


    $scope.previousMonth = function() {

        $scope.currentMonth--;

        if ($scope.currentMonth < 0) {
            $scope.currentMonth = 11;
            $scope.currentYear--;
        }

        buildCalendar();
    };


    $scope.nextMonth = function() {

        $scope.currentMonth++;

        if ($scope.currentMonth > 11) {
            $scope.currentMonth = 0;
            $scope.currentYear++;
        }

        buildCalendar();
    };


    buildCalendar();

};

sp_widget.css:
.leave-calendar-page {
  max-width: 1180px;
  margin: 30px auto;
  padding: 0 20px;
  font-family: Arial, sans-serif;
  color: #0f1b45;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.page-header h2 {
  margin: 0 0 6px;
  font-size: 28px;
  font-weight: 700;
}

.page-header p {
  margin: 0;
  color: #7c859a;
}

.back-link {
  color: #1769e0;
  text-decoration: none;
}

.calendar-card {
  background: #ffffff;
  border: 1px solid #e4e8ef;
  border-radius: 14px;
  padding: 22px;
  box-shadow: 0 3px 10px rgba(0,0,0,.04);
}

.calendar-toolbar {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 24px;
  margin-bottom: 20px;
}

.calendar-toolbar h3 {
  margin: 0;
  min-width: 190px;
  text-align: center;
  font-size: 20px;
}

.nav-btn {
  width: 38px;
  height: 38px;
  border: 1px solid #dfe4eb;
  border-radius: 8px;
  background: #ffffff;
  font-size: 22px;
  cursor: pointer;
}

.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
}

.calendar-days div {
  padding: 12px;
  text-align: center;
  font-size: 12px;
  font-weight: 700;
  background: #f7f9fc;
  border: 1px solid #edf0f4;
}

.calendar-cell {
  min-height: 125px;
  border: 1px solid #edf0f4;
  padding: 8px;
  background: #ffffff;
}

.calendar-cell.empty {
  background: #fafbfc;
}

.date-number {
  font-weight: 700;
  margin-bottom: 8px;
}

.leave-event {
  background: #e6f7ef;
  color: #166c4f;
  border-radius: 6px;
  padding: 6px 7px;
  margin-bottom: 5px;
  font-size: 11px;
}

.leave-event strong {
  display: block;
  margin-bottom: 2px;
}

.leave-event span {
  font-size: 10px;
}

.empty-message {
  margin-top: 18px;
  background: #ffffff;
  border: 1px solid #e4e8ef;
  border-radius: 12px;
  padding: 20px;
  text-align: center;
  color: #7c859a;
}

@media (max-width: 800px) {

  .page-header {
    display: block;
  }

  .back-link {
    display: inline-block;
    margin-top: 12px;
  }

  .calendar-card {
    overflow-x: auto;
  }

  .calendar-grid {
    min-width: 850px;
  }
}

sp_widget.script:
(function() {

    data.departmentName = "";
    data.departmentCode = "";
    data.customDepartmentId = "";
    data.approvedLeaves = [];

    // --------------------------------
    // GET LOGGED-IN USER
    // --------------------------------

    var userGR = new GlideRecord('sys_user');

    if (!userGR.get(gs.getUserID()))
        return;

    var standardDepartmentId =
        userGR.getValue('department') || "";

    data.departmentName =
        userGR.getDisplayValue('department') || "";

    if (!standardDepartmentId)
        return;


    // --------------------------------
    // GET STANDARD DEPARTMENT CODE
    // --------------------------------

    var deptGR = new GlideRecord('cmn_department');

    if (deptGR.get(standardDepartmentId)) {

        data.departmentCode =
            deptGR.getValue('id') || "";
    }

    if (!data.departmentCode)
        return;


    // --------------------------------
    // FIND CUSTOM DEPARTMENT
    // --------------------------------

    var customDeptGR =
        new GlideRecord(
            'x_snc_unified_hr_0_department'
        );

    customDeptGR.addQuery(
        'department_code',
        data.departmentCode
    );

    customDeptGR.setLimit(1);
    customDeptGR.query();

    if (customDeptGR.next()) {

        data.customDepartmentId =
            customDeptGR.getUniqueValue();
    }

    if (!data.customDepartmentId)
        return;


    // --------------------------------
    // GET APPROVED LEAVES
    // --------------------------------

    var leaveGR =
        new GlideRecord(
            'x_snc_unified_hr_0_leave_request'
        );

    leaveGR.addQuery(
        'department',
        data.customDepartmentId
    );

    leaveGR.addQuery(
        'status',
        'approved'
    );

    leaveGR.orderBy('start_date');
    leaveGR.query();

    while (leaveGR.next()) {

        data.approvedLeaves.push({

            number:
                leaveGR.getDisplayValue('number'),

            employee:
                leaveGR.getDisplayValue('requested_by'),

            leaveType:
                leaveGR.getDisplayValue('leave_type'),

            startDate:
                leaveGR.getValue('start_date'),

            endDate:
                leaveGR.getValue('end_date')

        });
    }

})();
